document.querySelectorAll('[data-propagation]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-propagation]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b))});const up=b.dataset.propagation==='up';document.querySelectorAll('[data-prop-arrow]').forEach(a=>a.textContent=up?'↑':'↓');document.getElementById('prop-explain').textContent=up?'CoreDNS signals can inform Cluster DNS. The projection uses the input evidence to determine any effect on the capability.':'A policy or attribute can flow from a higher-level entity to related services and workloads, according to the projection rules.'}));